'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={menu:'M4 6h16M4 12h16M4 18h16',pause:'M8 5v14M16 5v14',play:'m8 4 12 8-12 8z',back:'m14 5-7 7 7 7',light:'M9 18h6M10 21h4M8 15c-5-5-2-12 4-12s9 7 4 12l-1 2H9z',nozzle:'M5 3h14v10H5zM8 13l4 5 4-5M12 20v1',bed:'M3 19h18l-2-4H5zM7 3c-4 4 3 5 0 8M12 3c-4 4 3 5 0 8M17 3c-4 4 3 5 0 8',temp:'M10 4a2 2 0 0 1 4 0v10a4 4 0 1 1-4 0zM12 9v8',file:'M5 3h9l5 5v13H5zM14 3v5h5',spool:'M20 12a8 8 0 1 1-16 0 8 8 0 0 1 16 0M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0M20 12v9',move:'M12 2v20M2 12h20M8 6l4-4 4 4M8 18l4 4 4-4M6 8l-4 4 4 4M18 8l4 4-4 4',fan:'M12 10C3 1 20-2 15 10M14 12c12-3 8 14 0 3M10 14C8 26-5 15 8 12M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0',history:'M3 6v5h5M3 11a9 9 0 1 1 2 7M12 7v6l4 2',alert:'m12 3 10 18H2zM12 9v5M12 17v1',wifi:'M3 8a14 14 0 0 1 18 0M6 12a9 9 0 0 1 12 0M9 16a4 4 0 0 1 6 0M12 20h.01',power:'M12 2v10M6 5a9 9 0 1 0 12 0',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',speed:'M3 19a10 10 0 1 1 18 0M12 14l5-6M12 14v1',check:'m5 12 4 4L20 5',home:'m3 11 9-8 9 8M5 10v11h5v-7h4v7h5V10',plus:'M12 5v14M5 12h14',minus:'M5 12h14',chevron:'m9 5 7 7-7 7',up:'m5 15 7-7 7 7',down:'m5 9 7 7 7-7',stop:'M5 5h14v14H5z',clock:'M12 3a9 9 0 1 1 0 18 9 9 0 0 1 0-18M12 7v6h5',demo:'m8 3 12 9-12 9z',usb:'M12 3v17M8 7l4-4 4 4M6 10v4l6 4 6-4v-4',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.settings}"/></svg>`;
const defaults=()=>({status:'printing',progress:64,remaining:84,file:'Organizer.3mf',light:true,nozzle:220,bed:55,nozzleNow:220,bedNow:55,speed:'Standard',fans:[70,30,50],x:110,y:110,z:38,homed:false,step:10,slot:0,ams:true,drying:false,slots:[{material:'PLA',color:'#e7e5dc'},{material:'PETG',color:'#69a5bd'},{material:'PLA',color:'#c58c74'},{material:'ABS',color:'#7b8580'},{material:'PLA',color:'#8a9fb3'}],brightness:85,timeout:'5 Minuten',sound:true,night:false,power:true,autoOff:false,connected:true,developer:true,sensor:true,usb:true,empty:false,history:[{name:'Kabelclip.3mf',result:'Fertig',duration:'32 min'},{name:'Pflanztopf.3mf',result:'Fertig',duration:'2 h 12 min'}],messages:[],wifi:'Werkstatt',ip:'192.168.178.42',serial:'01P00A-DEMO',printOptions:{'Bett-Nivellierung':true,'Flow-Kalibrierung':false,'AMS nutzen':true,'Zeitraffer':false}});
let s=defaults();try{const saved=JSON.parse(localStorage.getItem('panda-soft-white-v1'));if(saved&&saved.slots&&saved.printOptions)s={...s,...saved};}catch(e){}
let route='home',parent='menu',fileSource='SD-Karte',fileIndex=0,slotIndex=0,wizardStep=0,wizardMode='laden',modalAction=null,previousFocus=null,toastTimer,asyncToken=0;
const files=[{name:'Organizer.3mf',time:'3 h 54 min',minutes:234,material:'PLA',weight:'86 g'},{name:'Kabelclip.3mf',time:'32 min',minutes:32,material:'PLA',weight:'12 g'},{name:'Pflanztopf.3mf',time:'2 h 12 min',minutes:132,material:'PETG',weight:'64 g'}];
const active=()=>['printing','paused','heating','levelling'].includes(s.status);
const save=()=>{try{localStorage.setItem('panda-soft-white-v1',JSON.stringify(s));}catch(e){}};
const btn=(text,action,cls='',attrs='')=>`<button class="btn raised ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const toggle=(label,key,value)=>`<div class="setting-row"><span>${label}</span><button class="switch" role="switch" aria-label="${label}" aria-checked="${!!value}" data-action="toggle:${key}"></button></div>`;
const tempTime=()=>s.remaining>=60?`${Math.floor(s.remaining/60)} h ${Math.round(s.remaining%60)} min`:`${Math.round(s.remaining)} min`;
const endTime=()=>{const t=new Date(Date.now()+s.remaining*60000);return t.toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'});};
const phase=()=>({printing:'Druck läuft',paused:'Druck pausiert',idle:'Bereit für Neues',heating:'Heizt auf',levelling:'Nivellierung',finished:'Druck fertig',offline:'Verbindung weg',error:'Druck angehalten',loading:'Verbinde …'}[s.status]||'Bereit');
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000);}
function go(to,from){route=to;if(from)parent=from;render();}
function header(title,sub='',back='menu'){return `<header class="page-header"><button class="back raised" data-action="nav:${back}" aria-label="Zurück">${icon('back')}</button><h2>${title}</h2><span class="sub">${sub}</span></header>`;}
function page(title,body,sub='',back='menu'){return `<section class="page">${header(title,sub,back)}<div class="page-content">${body}</div></section>`;}
function home(){const st=s.status;const isDone=st==='finished',isIdle=st==='idle',isOffline=!s.connected||st==='offline';return `<section class="home ${isOffline?'offline':''}"><header class="home-head"><h1>Panda Touch</h1><span class="connection">P1S · ${s.connected?'Verbunden':'Offline'}</span></header><div class="rail"><div class="progress-well" role="progressbar" aria-label="Druckfortschritt" aria-valuenow="${s.progress}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="height:${s.progress}%;${isDone?'background:#529773':''}"></div></div><strong>${s.progress} %</strong></div><div class="home-center"><div class="phase"><span class="status-dot ${st}"></span>${phase()}</div><div class="remaining"><small>${isDone?'Alles geschafft':isIdle?'Dein nächstes Projekt':isOffline?'Zuletzt bekannte Restzeit':'Restzeit'}</small><strong style="${isDone||isIdle?'font-size:48px':''}">${isDone?'100 % fertig':isIdle?'Druck starten':tempTime()}</strong></div><div class="finish sunken"><span>${isDone?'Druck abgeschlossen':'Fertig um'}</span><strong>${isDone?'✓':active()&&st!=='paused'&&s.connected?endTime():'–'}</strong></div><div class="job"><img class="object" src="organizer.png" alt="Vorschau eines weißen Schreibtisch-Organizers"><div><div class="job-title">${isIdle?'Datei auswählen':esc(s.file)}</div><div class="job-detail">${isIdle?'SD-Karte oder USB':`Schicht ${Math.round(s.progress*3)} / 300`}</div></div></div></div><div class="home-controls"><button class="raised" data-action="nav:menu">${icon('menu')}<span>Menü</span></button><button class="raised primary" data-action="${isDone?'ack-finish':isIdle?'nav:files':st==='error'?'nav:messages':'pause'}" ${isOffline?'disabled':''}>${icon(isDone?'check':isIdle?'file':st==='paused'?'play':st==='error'?'alert':'pause')}<span>${isDone?'Fertig':isIdle?'Dateien':st==='paused'?'Weiter':st==='error'?'Hinweis':'Pause'}</span></button><button class="raised" data-action="toggle:light" aria-pressed="${s.light}" ${isOffline?'disabled':''}><span class="light-dot ${s.light?'':'off'}"></span>${icon('light')}<span>Licht</span></button></div><div class="home-temps"><button data-action="nav:temperatures" aria-label="Düsentemperatur einstellen">${icon('nozzle')}Düse ${s.nozzleNow} °C</button><button data-action="nav:temperatures" aria-label="Betttemperatur einstellen">${icon('bed')}Bett ${s.bedNow} °C</button></div></section>`;}
function menu(){const items=[['Druck','control','speed'],['Temperaturen','temperatures','temp'],['Filament','filament','spool'],['Dateien','files','file'],['Bewegen','movement','move'],['Lüfter & Licht','fans','fan'],['Druckverlauf','history','history'],['Meldungen','messages','alert'],['Verbindung','connection','wifi'],['Panda PWR','power','power'],['System','system','settings'],['Demo-Zustände','demo','demo']];return page('Alles im Griff',`<div class="menu-grid">${items.map(([name,to,ic])=>`<button class="menu-tile raised" data-action="nav:${to}">${icon(ic)}${name}</button>`).join('')}</div>`,'Panda Touch','home');}
function control(){return page('Drucksteuerung',`<div class="row spread"><div><div class="label">${phase()}</div><div class="big-number">${s.progress} %</div></div>${btn(icon(s.status==='paused'?'play':'pause')+(s.status==='paused'?'Fortsetzen':'Pausieren'),'pause','primary',!active()||!s.connected?'disabled':'')}${btn('Druck abbrechen','cancel','danger',!active()?'disabled':'')}</div><div class="stack" style="margin-top:24px"><h3>Geschwindigkeit</h3><div class="grid2">${['Leise','Standard','Sport','Ludicrous'].map((v,i)=>btn(`${v} · ${[50,100,124,166][i]} %`,`speed:${v}`,s.speed===v?'selected':'','aria-pressed="'+(s.speed===v)+'"')).join('')}</div><p class="label">Höhere Geschwindigkeit kann die Druckqualität beeinflussen.</p></div>`);}
function temperatures(){return page('Temperaturen',`<div class="grid2">${[['Düse','nozzle',s.nozzleNow,300],['Bett','bed',s.bedNow,110]].map(([label,key,now,max])=>`<section class="panel raised"><h3>${label} <span class="muted">· Ist ${now} °C</span></h3><div class="temp-controls">${btn('−',`temp:${key}:-5`,'','aria-label="'+label+' 5 Grad kälter"')}<div><div class="big-number">${s[key]}°</div><div class="label">Sollwert</div></div>${btn('+',`temp:${key}:5`,'','aria-label="'+label+' 5 Grad wärmer"')}</div></section>`).join('')}</div><div class="row spread" style="margin-top:22px"><span class="label">Vorheizen</span>${btn('PLA','preset:PLA')}${btn('PETG','preset:PETG')}${btn('ABS','preset:ABS')}${btn('Aus','temp-off')}</div><div class="notice" style="margin-top:18px">Bauraum 36 °C · ${s.sensor?'Raum 23 °C · Luftfeuchte 42 %':'Kein Raumsensor angeschlossen'}</div>`);}
function filament(){const slots=s.ams?s.slots.slice(0,4):[];return page('Filament & AMS',`${s.ams?`<div class="row spread" style="margin-bottom:20px"><span>AMS · Feuchte 18 %</span>${btn(s.drying?'Trocknung stoppen':'Trocknung starten','dry',s.drying?'selected':'')}</div><div class="menu-grid" style="padding:0">${slots.map((slot,i)=>`<button class="slot raised" data-action="slot:${i}">${s.slot===i?'<span class="active-dot"></span>':''}<div class="spool" style="--spool:${slot.color}"></div><strong>Slot ${i+1} · ${slot.material}</strong><small>${s.slot===i?'Aktiv':'Bereit'}</small></button>`).join('')}</div>`:'<div class="notice">Kein AMS angeschlossen. Nutze die externe Spule.</div>'}<button class="list-item raised" data-action="slot:4" style="margin-top:20px"><div class="spool" style="--spool:${s.slots[4].color}"></div><div><strong>Externe Spule</strong><small>${s.slots[4].material} · ${s.slot===4?'Aktiv':'Bereit'}</small></div><span class="end">${icon('chevron')}</span></button>`,s.drying?'Trocknet · 4 h':'4 Slots + extern');}
function slotPage(){const slot=s.slots[slotIndex];return page(slotIndex===4?'Externe Spule':`AMS · Slot ${slotIndex+1}`,`<div class="grid2"><div class="panel raised"><div class="row"><div class="spool" style="--spool:${slot.color};width:70px;height:70px;border-width:14px"></div><div><div class="big-number">${slot.material}</div><div class="label">${s.slot===slotIndex?'Aktives Filament':'Verfügbar'}</div></div></div></div><div class="stack"><label class="field">Material<select data-field="slot-material">${['PLA','PETG','ABS','ASA','TPU'].map(x=>`<option ${x===slot.material?'selected':''}>${x}</option>`).join('')}</select></label><label class="row spread">Farbe<input type="color" value="${slot.color}" data-field="slot-color" aria-label="Filamentfarbe"></label></div></div><div class="grid2" style="margin-top:26px">${btn('Filament laden','wizard:laden','primary')}${btn('Filament entladen','wizard:entladen')}</div><p class="notice" style="margin-top:22px">Material und Farbe werden für diesen Slot gespeichert.</p>`,'','filament');}
function wizard(){const steps=wizardMode==='laden'?['Spule vorbereiten','Filament einführen','Filament fördern','Farbe prüfen']:['Druck vorbereiten','Düse aufheizen','Filament zurückziehen','Spule entnehmen'];const descriptions=wizardMode==='laden'?['Setze die Spule ein und prüfe, ob sich das Filament frei abwickeln kann.','Führe das Filament bis zum spürbaren Anschlag in den gewählten Eingang.','In der Demo wird das Filament jetzt bis zur Düse gefördert.','Ist die neue Farbe gleichmäßig zu sehen? Schließe den Vorgang ab.']:['Stelle sicher, dass gerade kein Druck läuft.','Die Düse wird in der Demo auf die benötigte Temperatur gebracht.','Das Filament wird in der Demo zurückgezogen.','Ziehe das Filament heraus und sichere das lose Ende an der Spule.'];return page(`Filament ${wizardMode}`,`<div class="wizard-track">${steps.map((_,i)=>`<span class="${i<=wizardStep?'on':''}"></span>`).join('')}</div><div class="panel raised"><div class="label">Schritt ${wizardStep+1} von 4</div><h3 style="font-size:26px;margin:10px 0">${steps[wizardStep]}</h3><p>${descriptions[wizardStep]}</p></div><div class="row spread" style="margin-top:24px">${btn('Vorgang verlassen','nav:slot')}${btn(wizardStep===3?'Abschließen':'Weiter','wizard-next','primary')}</div>`,'Geführter Ablauf','slot');}
function filesPage(){const available=fileSource==='SD-Karte'||s.usb;const list=s.empty||!available?[]:files;return page('Druckdateien',`<div class="pills">${['SD-Karte','USB-Stick'].map(x=>btn(icon(x==='SD-Karte'?'file':'usb')+x,`source:${x}`,fileSource===x?'selected':'')).join('')}</div>${!s.connected&&fileSource==='SD-Karte'?empty('wifi','Drucker nicht erreichbar','Die SD-Karte ist offline. Verbinde den Drucker erneut.','Verbindung öffnen','nav:connection'):list.length?list.map((f,i)=>`<button class="list-item raised" data-action="file:${i}"><img class="file-art" src="organizer.png" alt=""><div><strong>${f.name}</strong><small>${f.material} · ${f.weight}</small></div><span class="end">${f.time} ${icon('chevron')}</span></button>`).join(''):empty('file',available?'Keine Dateien':'Kein USB-Stick',available?'Hier erscheinen druckfertige 3MF-Dateien.':'Schließe einen USB-Stick an. In der Demo kannst du ihn unter Demo-Zustände einblenden.','Demo-Zustände','nav:demo')}`);}
function filePage(){const f=files[fileIndex];return page('Druck vorbereiten',`<div class="row spread"><div><h3>${f.name}</h3><p class="label">${f.time} · ${f.material} · ${f.weight}</p></div>${btn('Druck starten','start-print','primary')}</div><div style="margin-top:15px">${Object.entries(s.printOptions).map(([k,v])=>toggle(k,'option:'+k,v)).join('')}</div><p class="notice" style="margin-top:14px">Demo: Optionen werden gespeichert; der Druckstart wird simuliert.</p>`,'','files');}
function empty(ic,title,desc,label,action){return `<div class="empty">${icon(ic)}<h3>${title}</h3><p>${desc}</p>${label?btn(label,action,'primary'):''}</div>`;}
function movement(){return page('Bewegen',`<div class="row spread"><span>${s.homed?'Referenziert':'Nicht referenziert'}</span>${btn(icon('home')+'Referenzieren','home-axes')}</div><div class="pills" style="margin-top:18px">${[1,10,50].map(v=>btn(v+' mm','step:'+v,s.step===v?'selected':'')).join('')}</div><div class="grid2"><div class="axis-grid"><span></span>${btn('Y +','move:y:1') }<span></span>${btn('X −','move:x:-1')}${btn(icon('home'),'home-axes','','aria-label="Achsen referenzieren"')}${btn('X +','move:x:1')}<span></span>${btn('Y −','move:y:-1')}<span></span></div><div class="stack"><div class="row">${btn('Z +','move:z:1')}${btn('Z −','move:z:-1')}</div><div class="label">X ${s.x} · Y ${s.y} · Z ${s.z} mm</div><div class="row">${btn('Extruder +','extrude:1')}${btn('Extruder −','extrude:-1')}</div></div></div>`);}
function fans(){return page('Lüfter & Licht',`${toggle('Druckraumlicht','light',s.light)}${['Bauteillüfter','Hilfslüfter','Bauraumlüfter'].map((name,i)=>`<label class="field" style="margin-top:18px"><span class="row spread">${name}<strong id="fan-value-${i}">${s.fans[i]} %</strong></span><input type="range" min="0" max="100" step="10" value="${s.fans[i]}" data-field="fan:${i}" aria-label="${name}"></label>`).join('')}`);}
function history(){return page('Druckverlauf',s.history.length?s.history.map((h,i)=>`<button class="list-item raised" data-action="history:${i}">${icon(h.result==='Fertig'?'check':'stop')}<div><strong>${esc(h.name)}</strong><small>${h.result} · ${h.duration}</small></div><span class="end">Erneut drucken ${icon('chevron')}</span></button>`).join(''):empty('history','Noch keine Drucke','Deine abgeschlossenen Drucke erscheinen hier.','Dateien öffnen','nav:files'));}
function messages(){return page('Meldungen',s.messages.length?s.messages.map((m,i)=>`<section class="panel raised" style="margin-bottom:18px"><h3>${icon('alert')} ${esc(m.title)}</h3><p>${esc(m.text)}</p><div class="row" style="margin-top:16px">${btn('Problem behoben','resolve:'+i,'primary')}${btn('Ausblenden','dismiss:'+i)}</div></section>`).join(''):empty('check','Alles in Ordnung','Keine aktiven Fehlermeldungen oder Hinweise.','Zum Druckstatus','nav:home'));}
function connection(){return page('Verbindung',`<div class="row spread"><div><h3>${s.connected?'Drucker verbunden':'Drucker offline'}</h3><p class="label">${esc(s.wifi)} · Signal gut · MQTT lokal</p></div>${btn('Verbindung testen','reconnect','primary')}</div><div class="grid2" style="margin-top:22px"><label class="field">Drucker-IP<input type="text" data-field="ip" value="${esc(s.ip)}" inputmode="decimal"></label><label class="field">Seriennummer<input type="text" data-field="serial" value="${esc(s.serial)}"></label><label class="field">Access Code<input type="password" data-field="access" placeholder="Nur Demo-Eingabe" autocomplete="off"></label><label class="field">WLAN<select data-field="wifi"><option>${esc(s.wifi)}</option><option>Wohnzimmer</option><option>Neues WLAN</option></select></label></div><div class="row" style="margin-top:18px">${btn('WLAN einrichten','nav:setup')}${btn(s.developer?'Developer Mode: an':'Developer Mode: aus','toggle:developer',s.developer?'selected':'')}</div><p class="notice" style="margin-top:16px">Simulation ohne Netzwerkzugriff. Bitte keine echten Zugangsdaten eingeben.</p>`);}
function setup(){return page('WLAN einrichten',`<p class="notice">Ersteinrichtung · Deutsch · Beispielnetzwerke</p><div class="grid2" style="margin-top:20px"><label class="field">WLAN auswählen<select data-field="wifi"><option>Werkstatt</option><option>Wohnzimmer</option><option>Gastnetz</option></select></label><label class="field">WLAN-Passwort<input type="password" placeholder="Demo-Passwort" autocomplete="off"></label></div><div class="row" style="margin-top:24px">${btn('WLAN verbinden','setup-connect','primary')}</div><p class="label" style="margin-top:20px">Passwörter werden weder gespeichert noch gesendet.</p>`,'Schritt 1 von 2','connection');}
function power(){return page('Panda PWR',`<div class="panel raised"><div class="row spread"><div><div class="label">Drucker-Steckdose</div><div class="big-number">${s.power?'Eingeschaltet':'Ausgeschaltet'}</div></div>${btn(icon('power'),'power-switch',s.power?'selected':'','aria-label="Steckdose '+(s.power?'ausschalten':'einschalten')+'"')}</div></div><div style="margin-top:22px">${toggle('Nach Druckende automatisch ausschalten','autoOff',s.autoOff)}</div><div class="notice" style="margin-top:18px">Auto-Aus erst nach dem Abkühlen der Düse unter 50 °C. Steckdose und Abkühlen werden hier simuliert.</div>`,'Demo-Gerät');}
function system(){return page('System',`<label class="field"><span class="row spread">Helligkeit<strong id="brightness-value">${s.brightness} %</strong></span><input type="range" min="25" max="100" value="${s.brightness}" data-field="brightness" aria-label="Helligkeit"></label><div class="setting-row"><label for="timeout">Bildschirm-Timeout</label><select id="timeout" data-field="timeout" style="max-width:240px">${['Nie','1 Minute','5 Minuten','15 Minuten'].map(x=>`<option ${s.timeout===x?'selected':''}>${x}</option>`).join('')}</select></div>${toggle('Ton bei Druckende','sound',s.sound)}${toggle('Nachtmodus','night',s.night)}<div class="row" style="margin-top:20px">${btn(icon('moon')+'Bildschirm aus','sleep')}${btn('Neustart','restart')}${btn('Update prüfen','update')}</div><div class="row spread" style="margin-top:24px"><span class="label">Panda Touch Demo 1.0 · Akku 82 %</span>${btn('Zurücksetzen','factory','danger')}</div>`);}
function demo(){return page('Demo-Zustände',`<div class="grid3">${[['Druck läuft','printing'],['Pausiert','paused'],['Druck fertig','finished'],['Leerlauf','idle'],['Offline','offline'],['Fehler','error'],['Aufheizen','heating'],['Nivellieren','levelling'],['Verbindet …','loading']].map(([t,v])=>btn(t,'state:'+v,s.status===v?'selected':'')).join('')}</div><div style="margin-top:24px">${toggle('AMS angeschlossen','ams',s.ams)}${toggle('USB-Stick angeschlossen','usb',s.usb)}${toggle('Leere Dateiliste','empty',s.empty)}${toggle('Raumsensor angeschlossen','sensor',s.sensor)}</div><p class="notice" style="margin-top:14px">Nur simulierte Daten. Kein Befehl wird an einen echten Drucker gesendet.</p>`,'Zum Ausprobieren','home');}
function render(){const views={home,menu,control,temperatures,filament,slot:slotPage,wizard,files:filesPage,file:filePage,movement,fans,history,messages,connection,setup,power,system,demo};$('#app').innerHTML=(views[route]||home)();$('#device').style.filter=`brightness(${s.night?.65:(.7+.3*s.brightness/100)})`;save();}
function closeModal(){asyncToken++;$('#modal-root').innerHTML='';$('#app').inert=false;modalAction=null;if(previousFocus?.isConnected)previousFocus.focus();}
function modal(title,text,action,confirm='Bestätigen',danger=false){previousFocus=document.activeElement;$('#app').inert=true;modalAction=action;$('#modal-root').innerHTML=`<div class="modal-shade"><section class="modal-box" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${title}</h2><p>${text}</p><div class="row">${btn('Zurück','modal-close')}${btn(confirm,'modal-confirm','primary '+(danger?'danger':''))}</div></section></div>`;$('#modal-root button').focus();}
function busy(title,text,callback){modal(title,text,null,'Einen Moment …');const button=$('[data-action="modal-confirm"]');button.disabled=true;button.classList.add('busy');const token=++asyncToken;setTimeout(()=>{if(token!==asyncToken)return;closeModal();callback();},1300);}
function needConnection(){if(s.connected&&s.power)return true;toast('Drucker offline. Bitte zuerst verbinden.');return false;}
function pause(){if(!needConnection()||!active())return;s.status=s.status==='paused'?'printing':'paused';render();toast(s.status==='paused'?'Druck pausiert':'Druck wird fortgesetzt');}
function finish(){s.status='finished';s.progress=100;s.remaining=0;s.history.unshift({name:s.file,result:'Fertig',duration:'3 h 54 min'});if(s.sound){try{const ctx=new (window.AudioContext||window.webkitAudioContext)();const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=660;g.gain.value=.025;o.start();g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.4);o.stop(ctx.currentTime+.4);o.onended=()=>ctx.close();}catch(e){}}s.nozzle=0;s.bed=0;render();}
function startPrint(){if(!needConnection())return;const perform=()=>{s.file=files[fileIndex].name;s.remaining=files[fileIndex].minutes;s.progress=0;s.status='heating';s.nozzle=220;s.bed=55;go('home');toast('Druck gestartet · Düse und Bett heizen auf');};if(active()){modal('Laufenden Druck ersetzen?','Der aktuelle Druck wird in der Demo abgebrochen und die ausgewählte Datei gestartet.',()=>{s.history.unshift({name:s.file,result:'Abgebrochen',duration:tempTime()});perform();},'Neuen Druck starten',true);}else perform();}
function movementAction(axis,direction){if(!needConnection())return;if(!s.homed){toast('Bitte zuerst die Achsen referenzieren.');return;}const move=()=>{s[axis]=Math.max(0,Math.min(256,s[axis]+s.step*direction));render();toast(`${axis.toUpperCase()} → ${s[axis]} mm`);};if(active())modal('Während des Drucks verfahren?','Das kann das Druckteil beschädigen. Hier wird die Bewegung nur simuliert.',move,'Bewegen',true);else move();}
function stateChange(value){s.connected=value!=='offline';s.power=true;s.status=value;if(value==='finished'){finish();go('home');return;}if(value==='idle'){s.progress=0;s.remaining=0;}else{s.progress=64;s.remaining=84;}if(value==='error')s.messages=[{title:'Filamentzufuhr prüfen',text:'Das Filament kann nicht weitergefördert werden. Prüfe, ob die Spule frei läuft und der Schlauch nicht geknickt ist. Beispielmeldung, kein echter HMS-Code.'}];if(['heating','levelling'].includes(value))s.progress=0;go('home');if(value==='loading'){const token=++asyncToken;setTimeout(()=>{if(token===asyncToken&&s.status==='loading'){s.status='printing';s.connected=true;render();}},1800);}}
function dispatch(action){const [type,...args]=action.split(':');if(type==='nav'){go(args[0]);return;}if(type==='modal-close'){closeModal();return;}if(type==='modal-confirm'){const fn=modalAction;closeModal();if(fn)fn();return;}if(type==='toggle'){const key=args[0];if(key==='light'&&!needConnection())return;if(key==='option')s.printOptions[args.slice(1).join(':')]=!s.printOptions[args.slice(1).join(':')];else s[key]=!s[key];render();if(key==='light')toast(s.light?'Licht eingeschaltet':'Licht ausgeschaltet');return;}
if(type==='pause')return pause();
if(type==='ack-finish'){s.status='idle';s.progress=0;render();return;}
if(type==='cancel'){modal('Druck wirklich abbrechen?','Der Druck kann danach nicht fortgesetzt werden.',()=>{s.history.unshift({name:s.file,result:'Abgebrochen',duration:'Teilweise gedruckt'});s.status='idle';s.progress=0;s.remaining=0;s.nozzle=0;s.bed=0;go('home');toast('Druck abgebrochen');},'Druck abbrechen',true);return;}
if(type==='speed'){if(!needConnection())return;s.speed=args[0];render();toast('Geschwindigkeit: '+s.speed);return;}
if(type==='temp'){if(!needConnection())return;const [key,delta]=args;s[key]=Math.max(0,Math.min(key==='bed'?110:300,s[key]+Number(delta)));render();return;}
if(type==='preset'){if(!needConnection())return;[s.nozzle,s.bed]=({PLA:[220,55],PETG:[250,75],ABS:[260,100]})[args[0]];render();toast(args[0]+'-Vorheizen aktiviert');return;}
if(type==='temp-off'){if(!needConnection())return;const off=()=>{s.nozzle=s.bed=0;render();toast('Heizungen ausgeschaltet');};if(active())modal('Heizungen ausschalten?','Der aktive Druck wird dadurch beeinträchtigt.',off,'Ausschalten',true);else off();return;}
if(type==='dry'){if(!needConnection())return;s.drying=!s.drying;render();toast(s.drying?'AMS-Trocknung simuliert gestartet':'Trocknung gestoppt');return;}
if(type==='slot'){slotIndex=Number(args[0]);go('slot');return;}
if(type==='wizard'){if(!needConnection())return;if(active()){modal('Druck zuerst beenden','Filamentwechsel ist in diesem Ablauf nur ohne aktiven Druck möglich. Pausieren allein reicht hierfür nicht.',()=>go('control'),'Drucksteuerung');return;}wizardMode=args[0];wizardStep=0;go('wizard');return;}
if(type==='wizard-next'){if(wizardStep===3){s.slot=wizardMode==='laden'?slotIndex:-1;go('filament');toast('Filament '+(wizardMode==='laden'?'geladen':'entladen'));}else if(wizardStep===1){busy('Filament vorbereiten','Der Drucker führt den Schritt in der Demo aus.',()=>{wizardStep++;go('wizard');});}else{wizardStep++;render();}return;}
if(type==='source'){fileSource=args[0];render();return;}if(type==='file'){fileIndex=Number(args[0]);go('file');return;}if(type==='start-print')return startPrint();
if(type==='step'){s.step=Number(args[0]);render();return;}if(type==='move')return movementAction(args[0],Number(args[1]));
if(type==='home-axes'){if(!needConnection())return;const homeAxes=()=>busy('Achsen referenzieren','Die Home-Position wird in der Demo angefahren.',()=>{s.homed=true;s.x=0;s.y=0;s.z=0;render();toast('Alle Achsen referenziert');});if(active())modal('Während des Drucks referenzieren?','Eine Referenzfahrt kann das Druckteil beschädigen. Dieser Befehl wird nur simuliert.',homeAxes,'Referenzieren',true);else homeAxes();return;}
if(type==='extrude'){if(!needConnection())return;if(s.nozzleNow<170){toast('Düse zuerst auf mindestens 170 °C aufheizen.');return;}const extrude=()=>toast(Number(args[0])>0?'5 mm Filament gefördert':'5 mm Filament zurückgezogen');if(active())modal('Extruder während des Drucks bewegen?','Dies kann den laufenden Druck beeinträchtigen.',extrude,'Bewegen',true);else extrude();return;}
if(type==='history'){const h=s.history[Number(args[0])];fileIndex=Math.max(0,files.findIndex(f=>f.name===h.name));go('file');return;}
if(type==='resolve'||type==='dismiss'){s.messages.splice(Number(args[0]),1);if(type==='resolve'&&s.status==='error')s.status='paused';render();toast(type==='resolve'?'Hinweis bestätigt · Druck bleibt pausiert':'Meldung ausgeblendet');return;}
if(type==='reconnect'){if(!/^\d{1,3}(\.\d{1,3}){3}$/.test(s.ip)||s.ip.split('.').some(x=>Number(x)>255)){toast('Bitte eine gültige Drucker-IP eingeben.');return;}busy('Verbindung testen','Lokale Druckerverbindung wird simuliert.',()=>{if(!s.developer){s.connected=false;s.messages=[{title:'Developer Mode ist aus',text:'Aktiviere den Developer Mode am Drucker und teste die Verbindung erneut.'}];s.status='offline';render();toast('Developer Mode am Drucker aktivieren.');}else if(!s.power){s.connected=false;render();toast('Drucker-Steckdose ist ausgeschaltet.');}else{s.connected=true;if(s.status==='offline')s.status=s.progress>0?'paused':'idle';render();toast('Verbindung erfolgreich getestet');}});return;}
if(type==='setup-connect'){busy('WLAN verbinden','Verbindung zum gewählten Beispielnetzwerk wird hergestellt.',()=>{go('connection');toast('WLAN bereit · jetzt Druckerdaten prüfen');});return;}
if(type==='power-switch'){const power=()=>{s.power=!s.power;s.connected=s.power;if(!s.power){s.status='offline';s.nozzle=s.bed=0;}else s.status='idle';render();toast(s.power?'Steckdose eingeschaltet':'Steckdose ausgeschaltet');};if(s.power)modal('Drucker ausschalten?',active()?'Ein Druck ist aktiv. Ausschalten beendet den Druck sofort.':'Die Verbindung zum Drucker wird getrennt.',power,'Ausschalten',true);else power();return;}
if(type==='sleep'){sleep();return;}if(type==='wake'){document.querySelector('.sleep')?.remove();resetIdle();return;}
if(type==='restart'){modal('Panda Touch neu starten?','Die Demo startet neu. Deine Einstellungen bleiben gespeichert.',()=>busy('Neustart','Panda Touch startet …',()=>go('home')),'Neu starten');return;}
if(type==='update'){busy('Updates prüfen','Prüfung wird in der Demo simuliert.',()=>toast('Demo 1.0 · Du bist auf dem aktuellen Stand'));return;}
if(type==='factory'){modal('Einstellungen zurücksetzen?','Alle Demo-Einstellungen und der Demo-Verlauf werden auf den Anfangszustand gesetzt.',()=>{s=defaults();go('home');toast('Demo zurückgesetzt');},'Zurücksetzen',true);return;}
if(type==='state')return stateChange(args[0]);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)dispatch(b.dataset.action);});
document.addEventListener('input',e=>{const k=e.target.dataset.field;if(!k)return;const v=e.target.value;if(k.startsWith('fan:')){if(!s.connected){e.target.value=s.fans[Number(k.split(':')[1])];toast('Drucker offline');return;}const i=Number(k.split(':')[1]);s.fans[i]=Number(v);$('#fan-value-'+i).textContent=v+' %';}else if(k==='brightness'){s.brightness=Number(v);$('#brightness-value').textContent=v+' %';$('#device').style.filter=`brightness(${(.7+.3*s.brightness/100)})`;}else if(k==='slot-color'){s.slots[slotIndex].color=v;}else if(k==='slot-material'){s.slots[slotIndex].material=v;}else if(k!=='access')s[k]=v;save();});
document.addEventListener('change',e=>{if(['slot-material','slot-color'].includes(e.target.dataset.field))render();});
document.addEventListener('keydown',e=>{if(!$('#modal-root').children.length)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const items=[...$('#modal-root').querySelectorAll('button:not(:disabled),input,select')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
let idleTimer;function resetIdle(){clearTimeout(idleTimer);const minutes=parseInt(s.timeout);if(!Number.isNaN(minutes))idleTimer=setTimeout(sleep,minutes*60000);}
function sleep(){if(document.querySelector('.sleep'))return;const b=document.createElement('button');b.className='sleep';b.dataset.action='wake';b.innerHTML=icon('moon')+'<span>Gute Nacht.</span><small>Antippen zum Aufwecken</small>';$('#device').appendChild(b);b.focus();}
document.addEventListener('pointerdown',resetIdle);document.addEventListener('keydown',resetIdle);
let elapsed=0;setInterval(()=>{if(!s.connected)return;let changed=false;for(const key of ['nozzle','bed']){const actual=key+'Now';if(s[actual]!==s[key]){s[actual]+=Math.sign(s[key]-s[actual])*Math.min(key==='bed'?3:12,Math.abs(s[key]-s[actual]));changed=true;}}if(s.autoOff&&s.status==='finished'&&s.nozzleNow<50&&s.power){s.power=false;s.connected=false;toast('Düse abgekühlt · Auto-Aus ausgeführt');changed=true;}if(s.status==='heating'&&s.nozzleNow>=s.nozzle&&s.bedNow>=s.bed){s.status=s.printOptions['Bett-Nivellierung']?'levelling':'printing';elapsed=0;changed=true;}else if(s.status==='levelling'){elapsed+=2;if(elapsed>=8){s.status='printing';elapsed=0;changed=true;}}else if(s.status==='printing'){elapsed+=2;if(elapsed>=20){elapsed=0;s.progress=Math.min(100,s.progress+1);s.remaining=Math.max(0,s.remaining-2);changed=true;if(s.progress>=100){finish();return;}}}if(changed){save();if(['home','temperatures','power'].includes(route)&&!$('#modal-root').children.length)render();}},2000);
function resize(){const width=$('#stage').clientWidth;const scale=width/800;$('#device').style.transform=`scale(${scale})`;$('#stage').style.height=`${480*scale}px`;}
new ResizeObserver(resize).observe($('#stage'));window.addEventListener('resize',resize);
$('#scenario').onclick=()=>go('demo');$('#reset').onclick=()=>dispatch('factory');$('#fullscreen').onclick=()=>{if(!document.fullscreenElement)$('.studio').requestFullscreen?.();else document.exitFullscreen?.();};
render();resize();resetIdle();
